INSERT INTO categories (segment, product_type, title, intro_html, faq, sort_order) VALUES
('men', '', 'Men''s denim', '<p>Wholesale jeans, chinos, cargo trousers, denim jackets and shorts for men, made to order in our factory in Lahore. Choose a style, pick colors and sizes, and order from 100 pieces per color.</p><p>Every order is cut, sewn, washed and checked in-house, and is ready about 30 days after your deposit. We ship by air or sea, or hand the goods to your own forwarder.</p>', '[]', 10),
('men', 'jeans-pant', 'Men''s jeans pants', '<p>Slim stretch jeans in light, mid and dark washes, plus black, grey, olive and khaki. Stretch denim (98% cotton, 2% spandex), zip fly, sizes 30 to 40.</p><p>Need another fit, fabric or wash? We also make jeans to your own specification: send a tech pack or a reference sample and ask for a quote.</p>', '[{"question":"What is the minimum order?","answer":"100 pieces per color of a style. You can split them across the sizes; one set is 2 pieces of every size."},{"question":"How long does production take?","answer":"About 30 days after your deposit is confirmed. Shipping then takes about 5 to 10 days by air or 20 to 45 days by sea."},{"question":"Can I add my own labels and packaging?","answer":"Yes. We sew in your brand labels and use your hang tags and packaging. See the private label page for details."}]', 20),
('men', 'denim-jacket', 'Men''s denim jackets', '<p>Men''s denim jackets, made to order in our factory in Lahore. There are no styles in the online shop yet: send us a design, a photo or a sample and we will quote it, from 100 pieces per color.</p>', '[{"question":"How do I order a style that is not in the shop?","answer":"Send us a design, a tech pack, a photo or a sample through the quote form or on WhatsApp. We reply with a price, and you can order a sample first."}]', 30),
('men', 'jeans-short', 'Men''s jeans shorts', '<p>Men''s jeans shorts, made to order in our factory in Lahore. There are no styles in the online shop yet: send us a design, a photo or a sample and we will quote it, from 100 pieces per color.</p>', '[{"question":"How do I order a style that is not in the shop?","answer":"Send us a design, a tech pack, a photo or a sample through the quote form or on WhatsApp. We reply with a price, and you can order a sample first."}]', 40),
('men', 'cargo-trouser', 'Men''s cargo trousers', '<p>Relaxed cargo trousers with side pockets, in khaki, brown, olive and camo print. Heavy cotton twill (about 320 GSM), zip fly, sizes 30 to 40.</p><p>Made to order from 100 pieces per color and ready about 30 days after your deposit.</p>', '[{"question":"What is the minimum order?","answer":"100 pieces per color of a style. You can split them across the sizes; one set is 2 pieces of every size."},{"question":"How long does production take?","answer":"About 30 days after your deposit is confirmed. Shipping then takes about 5 to 10 days by air or 20 to 45 days by sea."},{"question":"Can I add my own labels and packaging?","answer":"Yes. We sew in your brand labels and use your hang tags and packaging. See the private label page for details."}]', 50),
('men', 'chino-pant', 'Men''s chino pants', '<p>Slim stretch chinos in cotton twill (about 320 GSM, 98% cotton, 2% spandex), in neutral and seasonal colors. Zip fly, sizes 30 to 40.</p><p>Every color is made to order from 100 pieces, with your own labels and packaging if you like.</p>', '[{"question":"What is the minimum order?","answer":"100 pieces per color of a style. You can split them across the sizes; one set is 2 pieces of every size."},{"question":"How long does production take?","answer":"About 30 days after your deposit is confirmed. Shipping then takes about 5 to 10 days by air or 20 to 45 days by sea."},{"question":"Can I add my own labels and packaging?","answer":"Yes. We sew in your brand labels and use your hang tags and packaging. See the private label page for details."}]', 60),
('women', '', 'Women''s denim', '<p>Wholesale jeans and denim skirts for women, made to order in Lahore: wide-leg, straight and stretch fits in light, mid and dark washes. Order from 100 pieces per color, split across the size range.</p><p>Production takes about 30 days after the deposit. Add your own labels and packaging for a private-label range.</p>', '[]', 70),
('women', 'jeans-pant', 'Women''s jeans pants', '<p>Wide-leg and stretch jeans for women in light, mid and dark washes. 11 to 12 oz denim, rigid or stretch, sizes 26 to 36.</p><p>Made to order from 100 pieces per color. We can also make your own designs: send a tech pack or a reference sample.</p>', '[{"question":"What is the minimum order?","answer":"100 pieces per color of a style. You can split them across the sizes; one set is 2 pieces of every size."},{"question":"How long does production take?","answer":"About 30 days after your deposit is confirmed. Shipping then takes about 5 to 10 days by air or 20 to 45 days by sea."},{"question":"Can I add my own labels and packaging?","answer":"Yes. We sew in your brand labels and use your hang tags and packaging. See the private label page for details."}]', 80),
('women', 'denim-jacket', 'Women''s denim jackets', '<p>Women''s denim jackets, made to order in our factory in Lahore. There are no styles in the online shop yet: send us a design, a photo or a sample and we will quote it, from 100 pieces per color.</p>', '[{"question":"How do I order a style that is not in the shop?","answer":"Send us a design, a tech pack, a photo or a sample through the quote form or on WhatsApp. We reply with a price, and you can order a sample first."}]', 90),
